import{_ as s,o,c as a,a2 as t}from"./chunks/framework.76ZGnlPi.js";const g=JSON.parse('{"title":"Promo Customer Onboarding Guide","description":"","frontmatter":{},"headers":[],"relativePath":"admin/promo-onboarding/index.md","filePath":"admin/promo-onboarding/index.md"}'),i={name:"admin/promo-onboarding/index.md"};function n(r,e,l,d,c,h){return o(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="promo-customer-onboarding-guide" tabindex="-1">Promo Customer Onboarding Guide <a class="header-anchor" href="#promo-customer-onboarding-guide" aria-label="Permalink to &quot;Promo Customer Onboarding Guide&quot;">​</a></h1><p>End-to-end workflow for giving customers access to the <strong>mitra frontend</strong> (<code>mitra.ahlaan.co.id</code> and its subdomains). Promo <strong>booking</strong> is <strong>closed registration</strong>. As of PR #456, being a <em>promo customer</em> (effective promo access ON) lets you <strong>log in</strong> but is <strong>not</strong> enough to book — you must also hold an <strong>approved mitra registration with a registration number</strong> (state <code>PARTNER</code>). A promo-enabled account without one is <code>REGISTRATION_REQUIRED</code>: hard-locked to the register form.</p><p><strong>Login is closed too, but to two groups, not one:</strong> a <em>promo customer</em> (below), <strong>or</strong> a <strong>mitra applicant</strong> — someone whose <a href="/ahlaan-train-docs/customer/mitra-registration/">mitra registration</a> is still open. An applicant can sign in from the moment they submit, but reaches <strong>only their own application</strong> (profile, application status, re-submit, their own documents); every other authenticated route on the host is <code>403</code>, wallet and invoices included. They price as HOLDER and cannot book. Approval promotes them to a promo customer on their <strong>existing</strong> session, with no re-login.</p><p>Two invariants worth knowing before you revoke anyone:</p><ul><li><strong><code>promoAccessEnabled: false</code> beats any registration.</strong> A banned account cannot let itself back in by submitting the self-service registration form.</li><li><strong>An approved registration is not a credential.</strong> Revoke a partner (deactivate their organization, or clear their override) and they are out — the old approved row does not bring them back as an &quot;applicant&quot;.</li></ul><p>Effective promo access is now <strong>necessary but not sufficient</strong> for booking: it is the <em>eligibility</em> half, and a numbered approved registration is the other half (state <code>PARTNER</code>). Whether a user is <strong>eligible</strong> (a promo customer) is decided by their <strong>effective promo access</strong>, a coalesce of a <strong>per-user override</strong> with their <strong>organization&#39;s</strong> flag:</p><table tabindex="0"><thead><tr><th><code>User.promoAccessEnabled</code> (override)</th><th>Effective promo access</th></tr></thead><tbody><tr><td><code>true</code></td><td><strong>ON</strong> — even with no organization, or a non-promo org</td></tr><tr><td><code>false</code></td><td><strong>OFF</strong> — even inside a promo-enabled organization</td></tr><tr><td><code>null</code> (default)</td><td><strong>inherit</strong> <code>Organization.promoAccessEnabled</code> — <strong>only for a B2B member</strong>; a B2C user (or an org-less user) ⇒ OFF</td></tr></tbody></table><p>So a promo customer does <strong>not</strong> need an organization — the org flag is just an optional <strong>bulk grant</strong>. (An individual, org-less partner is fully supported, but still needs an approved <strong>numbered</strong> registration to reach <code>PARTNER</code> and book.) <code>pricingTier</code> (<code>SILVER</code>/<code>GOLD</code>/<code>RESELLER</code>) is the separate, org-only <strong>pricing</strong> axis, orthogonal to access (<code>specialCustomPricingEnabled</code> is its deprecated <code>GOLD ⇔ true</code> mirror).</p><div class="warning custom-block"><p class="custom-block-title">B2C users do not inherit the org flag</p><p>Org-inherited promo access (<code>override = null</code>) applies <strong>only to genuine B2B org members</strong>. A <code>B2C</code> user ignores all organization-scoped rules, so the org&#39;s <code>promoAccessEnabled</code> flag does <strong>not</strong> grant them access. A B2C promo customer must be given an <strong>explicit</strong> per-user <code>promoAccessEnabled = true</code>. (This also means a member auto-demoted to B2C when their org was deactivated loses org-inherited promo access.)</p></div><hr><h2 id="quick-overview" tabindex="-1">Quick Overview <a class="header-anchor" href="#quick-overview" aria-label="Permalink to &quot;Quick Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Description</th></tr></thead><tbody><tr><td><strong>Purpose</strong></td><td>Grant / revoke promo-host login + booking access, per user or in bulk per org</td></tr><tr><td><strong>Access</strong></td><td>Admin only (<code>ADMIN</code> role)</td></tr><tr><td><strong>Control</strong></td><td>Effective promo access = per-user override coalesced with the org flag</td></tr><tr><td><strong>Orthogonal to</strong></td><td><code>pricingTier</code> (<code>SILVER</code>/<code>GOLD</code>/<code>RESELLER</code>) — pricing only, does not grant access (<code>specialCustomPricingEnabled</code> is its deprecated mirror)</td></tr></tbody></table><hr><h2 id="onboarding-paths" tabindex="-1">Onboarding paths <a class="header-anchor" href="#onboarding-paths" aria-label="Permalink to &quot;Onboarding paths&quot;">​</a></h2><h3 id="path-a-—-a-single-customer-no-organization" tabindex="-1">Path A — a single customer, no organization <a class="header-anchor" href="#path-a-—-a-single-customer-no-organization" aria-label="Permalink to &quot;Path A — a single customer, no organization&quot;">​</a></h3><p>Grant the per-user override directly. No org required.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># create the customer with the override on</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/api/v1/admin/users&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer &lt;admin-jwt&gt;&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;email&quot;: &quot;customer@example.com&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;name&quot;: &quot;Promo Customer&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;role&quot;: &quot;B2C&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;promoAccessEnabled&quot;: true</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  }&#39;</span></span></code></pre></div><p>Or flip an existing account on:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PATCH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/api/v1/admin/users/&lt;user-id&gt;/promo-access&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer &lt;admin-jwt&gt;&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{ &quot;enabled&quot;: true }&#39;</span></span></code></pre></div><p>B2B/B2C users are passwordless — the customer then logs in on the promo host via OTP or Google/Apple.</p><blockquote><p><strong>PR #456 — the promo grant alone no longer makes a booking partner.</strong> Granting the override puts the account in <code>REGISTRATION_REQUIRED</code> (login OK, <strong>cannot book</strong>). To reach the booking state <code>PARTNER</code> they must complete a <a href="/ahlaan-train-docs/customer/mitra-registration/">mitra registration</a> that an admin approves — which mints the registration number. Path A on its own is valid only for the legacy/grandfathered eligibility grant, not for onboarding a new booking partner. Verified live: <code>PATCH …/promo-access {&quot;enabled&quot;:true}</code> on an unnumbered account → <code>promoAccessLevel: REGISTRATION_REQUIRED</code>.</p></blockquote><h3 id="path-b-—-a-whole-organization-bulk-grant" tabindex="-1">Path B — a whole organization (bulk grant) <a class="header-anchor" href="#path-b-—-a-whole-organization-bulk-grant" aria-label="Permalink to &quot;Path B — a whole organization (bulk grant)&quot;">​</a></h3><p>Enable the org flag; every <strong>B2B</strong> member with override <code>null</code> (the default) inherits access. <strong>B2C members do not inherit</strong> the org flag — grant them individually via Path A (explicit <code>promoAccessEnabled = true</code>).</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PATCH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/api/v1/admin/organizations/&lt;org-id&gt;/promo-access&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer &lt;admin-jwt&gt;&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{ &quot;enabled&quot;: true }&#39;</span></span></code></pre></div><p>Attach users to that org via <code>POST /admin/users</code> (or <code>PATCH /admin/users/:id</code>) with <code>organizationId</code>. Toggle audit-logged as <code>PROMO_ACCESS_ENABLED / PROMO_ACCESS_DISABLED</code>, throttled 30/min.</p><h3 id="excluding-one-member-of-a-promo-org" tabindex="-1">Excluding one member of a promo org <a class="header-anchor" href="#excluding-one-member-of-a-promo-org" aria-label="Permalink to &quot;Excluding one member of a promo org&quot;">​</a></h3><p>Set that user&#39;s override to <code>false</code> — it wins over the org&#39;s bulk grant:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PATCH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/api/v1/admin/users/&lt;user-id&gt;/promo-access&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{ &quot;enabled&quot;: false }&#39;</span></span></code></pre></div><hr><h2 id="the-per-user-override-endpoint" tabindex="-1">The per-user override endpoint <a class="header-anchor" href="#the-per-user-override-endpoint" aria-label="Permalink to &quot;The per-user override endpoint&quot;">​</a></h2><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">PATCH</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/admin/users/:id/promo-access</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;enabled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;"> |</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;"> |</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><ul><li><code>true</code> → force promo access ON, <code>false</code> → exclude, <code>null</code> → clear the override (re-inherit the org flag).</li><li>Audit-logged as <code>USER_PROMO_ACCESS_SET</code>. Throttled 30/min. <code>404</code> on unknown user.</li></ul><p>You can also set <code>promoAccessEnabled</code> inline on <code>POST /admin/users</code> and <code>PATCH /admin/users/:id</code>.</p><hr><h2 id="auto-reset-on-org-membership-change" tabindex="-1">Auto-reset on org-membership change <a class="header-anchor" href="#auto-reset-on-org-membership-change" aria-label="Permalink to &quot;Auto-reset on org-membership change&quot;">​</a></h2><p>Whenever a user&#39;s <strong>organization membership changes</strong> — attach, switch, or detach — the per-user override is <strong>reset to <code>null</code></strong> so the user re-inherits the new context. A grant or exclusion made for a previous org never leaks onto a new one.</p><ul><li>Applies to <code>PATCH /admin/users/:id</code> (attach/switch/detach), user creation, and <strong>B2B application approval</strong> (which attaches the approved user to a new org).</li><li><strong>Exception:</strong> if the same request also sends an explicit <code>promoAccessEnabled</code>, that value wins (attach-and-grant, or attach-and-exclude, atomically).</li><li>A no-op org value (unchanged id, or empty string) does <strong>not</strong> reset.</li><li>Consequence: <strong>detaching or switching an org clears any per-user grant</strong> — a standalone promo customer who later gets attached/detached must be re-granted with the override.</li></ul><hr><h2 id="kick-a-user-from-an-organization" tabindex="-1">Kick a user from an organization <a class="header-anchor" href="#kick-a-user-from-an-organization" aria-label="Permalink to &quot;Kick a user from an organization&quot;">​</a></h2><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">PATCH</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/admin/users/:id      { &quot;organizationId&quot;: null }</span></span></code></pre></div><ul><li>Send <strong>explicit <code>null</code></strong>; <code>&quot;&quot;</code> is a no-op; omitting the field = no change.</li><li>Detach clears the org grant <strong>and</strong> resets the override to <code>null</code> (per the rule above) → the user&#39;s effective promo access drops to OFF unless re-granted.</li></ul><hr><h2 id="seeing-who-is-a-promo-customer" tabindex="-1">Seeing who is a promo customer <a class="header-anchor" href="#seeing-who-is-a-promo-customer" aria-label="Permalink to &quot;Seeing who is a promo customer&quot;">​</a></h2><p><strong>Customer list / detail</strong> (<code>GET /admin/users</code>, <code>GET /admin/users/:id</code>) expose:</p><ul><li><code>promoAccessEnabled</code> — the raw per-user override (<code>true</code> / <code>false</code> / <code>null</code>).</li><li><code>effectivePromoAccess</code> — the resolved boolean the gate actually enforces.</li><li>nested <code>organization.promoAccessEnabled</code> — the org&#39;s bulk-grant flag.</li></ul><p><strong>Filter customers by effective promo access:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/admin/users?promoAccessEnabled=true    # promo customers</span></span>
<span class="line"><span>GET /api/v1/admin/users?promoAccessEnabled=false   # everyone else</span></span></code></pre></div><p>The filter is on <strong>effective</strong> access — it matches both override-<code>true</code> users and override-<code>null</code> users inheriting a promo-enabled org.</p><p><strong>Filter organizations:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/admin/organizations?promoAccessEnabled=true</span></span>
<span class="line"><span>GET /api/v1/admin/organizations?specialCustomPricingEnabled=true</span></span></code></pre></div><p>Both flags are also shown on the org list/detail responses.</p><hr><h2 id="downgrading" tabindex="-1">Downgrading <a class="header-anchor" href="#downgrading" aria-label="Permalink to &quot;Downgrading&quot;">​</a></h2><ul><li><strong>One user:</strong> <code>PATCH /admin/users/:id/promo-access { &quot;enabled&quot;: false }</code> (hard exclude) or <code>{ &quot;enabled&quot;: null }</code> (inherit — OFF if org-less / non-promo org).</li><li><strong>A whole org:</strong> <code>PATCH /admin/organizations/:id/promo-access { &quot;enabled&quot;: false }</code>. Members with override <code>null</code> lose access; members with override <code>true</code> keep it (org-independent grant).</li><li>Revoking promo access does <strong>not</strong> strand in-flight bookings — booking lifecycle endpoints (list/detail, passenger updates, ticket download, cancel) are not promo-gated.</li></ul><hr><h2 id="deploy-note" tabindex="-1">Deploy note <a class="header-anchor" href="#deploy-note" aria-label="Permalink to &quot;Deploy note&quot;">​</a></h2><p>The migration adds <code>User.promoAccessEnabled</code> as <code>NULL</code> (inherit) for every user and <code>Organization.promoAccessEnabled=false</code> for every org — so at deploy all customers are blocked from promo login/booking, by design. Immediately after migrating, grant access per user (Path A) or per org (Path B). Every org already promo-enabled keeps granting its members (override defaults to inherit).</p><hr><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related Documentation&quot;">​</a></h2><ul><li><a href="/ahlaan-train-docs/admin/users/">Users Management</a> — override field, <code>effectivePromoAccess</code>, the promo filter, and the per-user promo-access endpoint.</li><li><a href="/ahlaan-train-docs/admin/organizations/">Organizations Management</a> — the org bulk-grant flag and its list filters.</li><li><a href="/ahlaan-train-docs/admin/special-custom-b2b-pricing/">Special Custom B2B Pricing</a> — the orthogonal pricing axis (<code>pricingTier</code>).</li><li><a href="/ahlaan-train-docs/customer/register-login/#promo-host-promo-ahlaan-co-id">Register / Login → Promo Host</a> — the closed-registration login behavior promo customers experience.</li></ul>`,60)])])}const u=s(i,[["render",n]]);export{g as __pageData,u as default};
